import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Search, GlassWater } from 'lucide-react';
import './App.css';

function App() {
  const [cocktails, setCocktails] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchCocktails = async (query = '') => {
    setLoading(true);
    try {
      const endpoint = query 
        ? `https://www.thecocktaildb.com/api/json/v1/1/search.php?s=${query}`
        : `https://www.thecocktaildb.com/api/json/v1/1/random.php`;

      const response = await axios.get(endpoint);
      const data = response.data.drinks;
      setCocktails(data ? (Array.isArray(data) ? data : [data[0]]) : []);
    } catch (error) {
      console.error("Error fetching cocktails:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCocktails();
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    fetchCocktails(searchTerm);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1><GlassWater style={{marginRight: '10px'}} /> Coctelería Verde Grillo</h1>
      </header>

      <form className="search-container" onSubmit={handleSearch}>
        <input 
          className="search-input"
          type="text" 
          placeholder="Busca un cóctel..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <button type="submit" className="search-button">
          <Search size={20} />
        </button>
      </form>

      {loading ? (
        <p>Cargando deliciosos cócteles...</p>
      ) : (
        <div className="cocktail-grid">
          {cocktails.map((cocktail) => (
            <div key={cocktail.idDrink} className="cocktail-card">
              <img src={cocktail.strDrinkThumb} alt={cocktail.strDrink} />
              <h3>{cocktail.strDrink}</h3>
              <p>{cocktail.strCategory} | {cocktail.strAlcoholic}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
